{
  "name": "deterministic_gridworld_3x3",
  "version": "1.0",
  "description": "A simple deterministic 3x3 grid-world. States are (row, col) pairs, 0-indexed from the top-left corner. All transitions are deterministic: each action moves one cell in the intended direction, and moves that would leave the grid leave the agent in place.",
  "grid": {
    "rows": 3,
    "cols": 3
  },
  "states": [
    [0, 0], [0, 1], [0, 2],
    [1, 0], [1, 1], [1, 2],
    [2, 0], [2, 1], [2, 2]
  ],
  "actions": [
    { "id": 0, "name": "up", "delta": [-1, 0] },
    { "id": 1, "name": "down", "delta": [1, 0] },
    { "id": 2, "name": "left", "delta": [0, -1] },
    { "id": 3, "name": "right", "delta": [0, 1] }
  ],
  "dynamics": {
    "type": "deterministic",
    "transition_rule": "next_state = state + action.delta if the result is within the grid, else next_state = state",
    "off_grid_behavior": "stay_in_place"
  },
  "start_state": [0, 0],
  "terminal_states": [[2, 2]],
  "rewards": {
    "per_step": -1.0,
    "on_reaching_terminal": 0.0,
    "note": "Agent receives -1 per step until the terminal state is reached; the terminal transition itself yields no additional reward."
  },
  "episode": {
    "termination": "agent enters a terminal state",
    "max_steps": 100
  }
}
